import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, float, hash, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group, Color, DoubleSide, SRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-collection-card-3';

  const holder = new Group();
  group.add(holder);

  // Atlas region: 512 x 320 -> aspect 1.6
  const W = 1.6;
  const H = 1.0;

  // --- Main card surface (ceramic-grain texture) ---
  const cardGeo = new PlaneGeometry(W, H);
  const cardMat = new MeshBasicNodeMaterial();
  cardMat.side = DoubleSide;
  cardMat.toneMapped = true;
  cardMat.color = new Color('#e8ecf2');
  const cardMesh = new Mesh(cardGeo, cardMat);
  holder.add(cardMesh);

  // --- Engineered gradient surface overlay (edge darkening) ---
  const overlayMat = new MeshBasicNodeMaterial();
  overlayMat.transparent = true;
  overlayMat.depthWrite = false;
  overlayMat.side = DoubleSide;
  const t = uv();
  const topDark = smoothstep(float(0.6), float(1.0), t.y).mul(0.35);
  const bottomDark = smoothstep(float(0.6), float(1.0), t.y.oneMinus()).mul(0.28);
  const leftDark = smoothstep(float(0.6), float(1.0), t.x).mul(0.20);
  const rightDark = smoothstep(float(0.6), float(1.0), t.x.oneMinus()).mul(0.20);
  const vig = topDark.add(bottomDark).add(leftDark).add(rightDark);
  overlayMat.colorNode = vec3(0.04, 0.04, 0.06);
  overlayMat.opacityNode = vig.mul(0.85);
  const overlayMesh = new Mesh(cardGeo, overlayMat);
  overlayMesh.position.z = 0.001;
  holder.add(overlayMesh);

  // --- Subtle grain overlay ---
  const grainMat = new MeshBasicNodeMaterial();
  grainMat.transparent = true;
  grainMat.depthWrite = false;
  grainMat.side = DoubleSide;
  const g = hash(uv().mul(float(900.0)));
  grainMat.colorNode = vec3(0.0, 0.0, 0.0);
  grainMat.opacityNode = g.mul(0.045);
  const grainMesh = new Mesh(cardGeo, grainMat);
  grainMesh.position.z = 0.002;
  holder.add(grainMesh);

  // --- Accent edge (signal red micro-underline) ---
  const accentGeo = new PlaneGeometry(W * 0.18, 0.014);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.color = new Color('#ff2a38');
  accentMat.toneMapped = true;
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-W * 0.5 + W * 0.09 + 0.05, -H * 0.5 + 0.07, 0.003);
  holder.add(accentMesh);

  // --- Async texture load (attached post-creation) ---
  let loadedTexture = null;
  const imageUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    cardMat.map = tex;
    cardMat.needsUpdate = true;
    loadedTexture = tex;
  }).catch(() => {});

  // --- Entrance motion: rise-in + weighted-settle ---
  holder.position.y = 0.4;
  const tl = gsap.timeline();
  tl.to(holder.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(holder.scale, { x: 1.04, y: 1.04, duration: 0.45, ease: 'power2.out' }, '-=0.35')
    .to(holder.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    cardGeo.dispose();
    accentGeo.dispose();
    cardMat.dispose();
    overlayMat.dispose();
    grainMat.dispose();
    accentMat.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return group;
}
